		return m_spawnFrame;

	UnsignedInt pick = GetGameLogicRandomValue(0, count - 1, CIVILIAN_SPAWN_FILE, 0x74);
	Object *runToObject = 0;
	for (UnsignedInt i = 0; i <= pick; ++i)
		runToObject = iter.next();

